/* Import base styles from pi-web-ui (compiled Tailwind + KaTeX + themes).
   MUST come before the local Tailwind import: pi-web-ui's compiled bundle
   contains base utilities (.hidden, .flex, .w-full) without responsive
   variants, and whichever stylesheet is imported later wins within the
   merged `utilities` layer. Importing it first lets local responsive
   variants (e.g. `sm:flex`) override its base utilities as Tailwind
   intends. */
@import "@earendil-works/pi-web-ui/app.css";

/* Import Tailwind CSS */
@import "tailwindcss";

/* Retro theme for landing, tutorial, blog */
@import "./styles/retro.css";

/* ────────────────────────────────────────────────────────────────
   RETRO THEME OVERRIDES — overrides pi-web-ui default tokens
   with retro paper/terminal values so the entire app feels
   consistent with the landing page aesthetic.
   ──────────────────────────────────────────────────────────────── */

:root {
  /* Core retro brand tokens globally available */
  --paper: #f1ece0;
  --paper-deep: #e9e2d2;
  --ink: #1c211b;
  --ink-soft: #4a5247;
  --green: #1e9b50;
  --green-deep: #14743c;
  --green-wash: #ddebdd;
  --crt: #0c1510;
  --crt-edge: #1b2a1f;
  --phosphor: #4be388;
  --phosphor-dim: #2e9a5c;
  --amber: #e8a33d;
  --red: #d5604b;
  --line: rgba(28, 33, 27, 0.22);
  --line-soft: rgba(28, 33, 27, 0.12);
  --accent-green: #1e9b50;
  --shadow-card:
    0 1px 0 rgba(28, 33, 27, 0.06), 0 10px 28px -18px rgba(28, 33, 27, 0.35);
  --mono-display:
    "Space Mono", ui-monospace, "Cascadia Mono", Menlo, monospace;
  --mono-body:
    "JetBrains Mono", ui-monospace, "Cascadia Mono", Menlo, monospace;
  --font-ui:
    system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  /* Paper palette (light mode — default) */
  --background: #f1ece0;
  --foreground: #1c211b;
  --card: #f6f2e8;
  --card-foreground: #1c211b;
  --popover: #f6f2e8;
  --popover-foreground: #1c211b;
  --primary: #1e9b50;
  --primary-foreground: #ffffff;
  --secondary: #e9e2d2;
  --secondary-foreground: #1c211b;
  --muted: #e9e2d2;
  --muted-foreground: #4a5247;
  --accent: #ddebdd;
  --accent-foreground: #14743c;
  --destructive: #b9432e;
  --destructive-foreground: #ffffff;
  --border: #1c211b;
  --input: #1c211b;
  --ring: #1e9b50;
  --chart-1: #1e9b50;
  --chart-2: #14743c;
  --chart-3: #2e9a5c;
  --chart-4: #e8a33d;
  --chart-5: #d5604b;
  --sidebar: #e9e2d2;
  --sidebar-foreground: #1c211b;
  --sidebar-primary: #1e9b50;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #ddebdd;
  --sidebar-accent-foreground: #14743c;
  --sidebar-border: #1c211b;
  --sidebar-ring: #1e9b50;
  --font-sans: "Roboto", "Segoe UI", Arial, sans-serif;
  --font-serif: Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono:
    "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas,
    "Liberation Mono", "Courier New", monospace;
  --radius: 0.25rem;
}

.dark {
  /* CRT phosphor palette (dark mode) */
  --paper: #0c1510;
  --paper-deep: #0a110d;
  --ink: #dcefe0;
  --ink-soft: #9dbfa8;
  --line: rgba(75, 227, 136, 0.28);
  --line-soft: rgba(75, 227, 136, 0.14);
  --shadow-card:
    0 1px 0 rgba(0, 0, 0, 0.4), 0 10px 28px -18px rgba(0, 0, 0, 0.8);
  --font-ui:
    system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --background: #0c1510;
  --foreground: #dcefe0;
  --card: #11201a;
  --card-foreground: #dcefe0;
  --popover: #11201a;
  --popover-foreground: #dcefe0;
  --primary: #4be388;
  --primary-foreground: #0c1510;
  --secondary: #1b2a1f;
  --secondary-foreground: #dcefe0;
  --muted: #16231b;
  --muted-foreground: #8fbf9e;
  --accent: rgba(75, 227, 136, 0.12);
  --accent-foreground: #4be388;
  --destructive: #d5604b;
  --destructive-foreground: #f1ece0;
  --border: rgba(75, 227, 136, 0.28);
  --input: rgba(75, 227, 136, 0.32);
  --ring: #4be388;
  --chart-1: #4be388;
  --chart-2: #2e9a5c;
  --chart-3: #1e9b50;
  --chart-4: #e8a33d;
  --chart-5: #d5604b;
  --sidebar: #0a110d;
  --sidebar-foreground: #dcefe0;
  --sidebar-primary: #4be388;
  --sidebar-primary-foreground: #0c1510;
  --sidebar-accent: rgba(75, 227, 136, 0.12);
  --sidebar-accent-foreground: #4be388;
  --sidebar-border: rgba(75, 227, 136, 0.28);
  --sidebar-ring: #4be388;
  --font-sans: "Roboto", "Segoe UI", Arial, sans-serif;
  --font-serif: Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono:
    "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas,
    "Liberation Mono", "Courier New", monospace;
  --radius: 0.25rem;
}

/* Custom Keating styles */
html,
body,
#root {
  height: 100%;
  margin: 0;
  padding: 0;
}

/* App pages use the configurable sans font */
body {
  font-family: var(--font-sans);
}

input,
textarea,
select {
  font-family: var(--font-ui);
}

.font-ui {
  font-family: var(--font-ui);
}

/* Smooth theme transitions (except background which can flash) */
html {
  transform: scale(100%);
  font-size: 130%;
  transition: color-scheme 0.2s ease;
}

/* Theme-aware highlight color */
::selection {
  background: var(--green);
  color: #ffffff;
}

.dark ::selection {
  background: var(--phosphor);
  color: var(--crt);
}

/* Focus ring uses accent green */
:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

/* Button hover/active micro-interactions */
button:not(:disabled) {
  transition:
    transform 0.08s ease-out,
    background-color 0.12s ease;
}

/* Firefox scrollbars */
* {
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

.chat-page-shell {
  height: 100vh;
  height: 100dvh;
  min-height: 100vh;
  min-height: 100dvh;
}

.chat-page-panel {
  height: 100%;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.chat-header {
  min-width: 0;
}

.chat-brand {
  max-width: min(44vw, 14rem);
  border: 2px solid transparent;
  transition:
    background-color 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease,
    transform 0.15s ease,
    box-shadow 0.15s ease;
}

.chat-brand img {
  transition:
    transform 0.15s ease,
    filter 0.15s ease;
}

.chat-brand:hover,
.chat-brand:focus-visible {
  border-color: color-mix(in srgb, var(--chat-accent) 55%, transparent);
  background: color-mix(in srgb, var(--chat-accent) 12%, transparent);
  color: var(--chat-accent);
  box-shadow: 2px 2px 0 color-mix(in srgb, var(--chat-accent) 55%, transparent);
  transform: translateY(-1px);
}

.chat-brand:hover img,
.chat-brand:focus-visible img {
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--chat-accent) 55%, transparent));
  transform: rotate(-3deg) scale(1.06);
}

.chat-brand:active {
  box-shadow: 1px 1px 0 color-mix(in srgb, var(--chat-accent) 55%, transparent);
  transform: translate(1px, 1px);
}

.chat-actions {
  overscroll-behavior-x: contain;
  scroll-snap-type: x proximity;
}

.chat-action-button,
.chat-actions > button {
  width: 2.25rem;
  height: 2.25rem;
  padding: 0;
}

/* Horizontal scroll-snap only kicks in on viewports where the desktop
   action row actually overflows (mid-sized tablet / short landscape phones).
   On small screens we remove the snap so buttons don't pin to the right edge
   and reserve phantom horizontal space. */
@media (min-width: 48rem) {
  .chat-action-button,
  .chat-actions > button {
    scroll-snap-align: end;
  }
}

/*
 * Responsive header visibility — driven from unlayered CSS (not Tailwind
 * `md:`/`lg:` variants), because Tailwind is compiled twice in this app
 * (app.css + pi-web-ui) and the duplicated base `.hidden`/`.inline-flex`
 * emitted last would otherwise clobber the responsive variants at all widths.
 * `.chat-only-desktop`: inline header actions, shown at md+ (>= 48rem).
 * `.chat-only-compact`: overflow-menu duplicates, shown below md (< 48rem).
 */
.chat-only-desktop {
  display: none;
}
@media (min-width: 48rem) {
  .chat-only-desktop {
    display: inline-flex;
  }
  .chat-only-compact {
    display: none;
  }
}

@media (max-width: 768px) {
  .chat-page-shell .chat-action-button,
  .chat-page-shell .chat-actions > button {
    width: 2.25rem;
    height: 2.25rem;
    min-width: 2.25rem;
    min-height: 2.25rem;
    padding: 0;
    font-size: 0.875rem;
  }

  .chat-page-shell .chat-action-button svg,
  .chat-page-shell .chat-actions > button svg {
    width: 1rem;
    height: 1rem;
  }
}

@media (max-width: 640px) {
  .chat-page-shell .chat-action-button,
  .chat-page-shell .chat-actions > button {
    width: 2rem;
    height: 2rem;
    min-width: 2rem;
    min-height: 2rem;
    padding: 0;
  }
}

:root {
  --color-primary: #1e9b50;
}

.dark {
  --color-primary: #4be388;
}

message-editor textarea {
  font-family: var(--font-ui) !important;
  color: var(--color-foreground) !important;
  -webkit-text-fill-color: var(--color-foreground) !important;
  caret-color: var(--color-foreground) !important;
  opacity: 1 !important;
  text-shadow: none !important;
}

message-editor textarea::placeholder {
  -webkit-text-fill-color: var(--color-muted-foreground) !important;
}

/* Retro-styled keating header for non-chat pages */
.keating-header {
  background: var(--background);
  backdrop-filter: blur(10px);
  border-bottom: 2px solid var(--border);
  padding: 0.75rem 1rem;
}

.dark .keating-header {
  background: var(--background);
  border-bottom: 2px solid var(--border);
}

.local-model-badge {
  background: var(--color-primary);
  color: white;
  font-size: 0.75rem;
  padding: 0.25rem 0.5rem;
  border-radius: 9999px;
}

/* Mobile-friendly improvements for mono UI.
   Scoped to `body:not(.chat-shell-active)` so the dense chat UI manages its
   own button sizes — global 44px touch targets blow up the chat header icons
   and the composer send button. */
@media (max-width: 768px) {
  body:not(.chat-shell-active) button,
  body:not(.chat-shell-active) [role="button"],
  body:not(.chat-shell-active) .btn {
    min-height: 44px;
    min-width: 44px;
    padding: 0.75rem 1rem;
    font-size: 1rem;
  }

  body:not(.chat-shell-active) input,
  body:not(.chat-shell-active) textarea,
  body:not(.chat-shell-active) select {
    min-height: 44px;
    font-size: 16px; /* Prevents iOS zoom on focus */
    padding: 0.75rem;
  }

  body:not(.chat-shell-active) .gap-1 {
    gap: 0.5rem !important;
  }
  body:not(.chat-shell-active) .gap-2 {
    gap: 0.75rem !important;
  }
  body:not(.chat-shell-active) .gap-3 {
    gap: 1rem !important;
  }

  header .text-lg {
    font-size: 1.125rem;
  }

  dialog button,
  [role="dialog"] button {
    width: 100%;
    margin-bottom: 0.5rem;
  }

  [role="dialog"] .dialog-icon-button {
    width: 2rem !important;
    margin-bottom: 0 !important;
  }

  [role="dialog"] .dialog-compact-button {
    width: auto !important;
    margin-bottom: 0 !important;
  }

  body:not(.chat-shell-active) button svg,
  body:not(.chat-shell-active) [role="button"] svg {
    width: 1.5rem;
    height: 1.5rem;
  }

  .settings-panel,
  [class*="settings-panel"] {
    padding: 1.5rem;
  }

  body:not(.chat-shell-active) select,
  body:not(.chat-shell-active) [role="combobox"] {
    min-height: 48px;
    padding: 0.75rem 2.5rem 0.75rem 1rem;
  }

  .close-btn,
  [aria-label="close"],
  button[title="Close"] {
    min-width: 48px;
    min-height: 48px;
    padding: 0.75rem;
  }
}

@media (max-width: 480px) {
  body:not(.chat-shell-active) button,
  body:not(.chat-shell-active) [role="button"] {
    min-height: 48px;
    padding: 0.875rem 1.25rem;
  }

  body {
    font-size: 16px;
  }

  .button-group,
  [class*="button-group"] {
    flex-direction: column;
    width: 100%;
  }

  .button-group button,
  [class*="button-group"] button {
    width: 100%;
  }
}

/* Scrollbar utilities */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Fix markdown headings for dark mode contrast */
.markdown-content h1,
.markdown-content h2,
.markdown-content h3,
.markdown-content h4,
.markdown-content h5,
.markdown-content h6 {
  color: var(--foreground);
}

/* Fix KaTeX math rendering in dark mode */
.markdown-content .katex {
  color: var(--foreground);
}

/* Fix inline code contrast */
.markdown-content code:not(.hljs) {
  color: var(--foreground);
}

/* ─── Chat styling ─── */
.chat-page-shell {
  --chat-paper: #f1ece0;
  --chat-ink: #1c211b;
  --chat-accent: #1e9b50;
}

.dark .chat-page-shell {
  --chat-paper: #0c1510;
  --chat-ink: #dcefe0;
  --chat-accent: #4be388;
}

.chat-page-shell .chat-header {
  background: var(--chat-paper);
  border-bottom: 2px solid var(--chat-ink);
}

.dark .chat-page-shell .chat-header {
  background: var(--chat-paper);
  border-bottom: 2px solid var(--chat-ink);
}

.chat-page-shell .composer-root {
  background: var(--chat-paper);
  border: 2px solid var(--chat-ink);
  box-shadow: 4px 4px 0 var(--chat-ink);
  transition:
    box-shadow 0.15s,
    transform 0.15s;
}

.chat-page-shell .composer-root:focus-within {
  box-shadow: 2px 2px 0 var(--chat-ink);
}

.chat-page-shell.session-forking .chat-page-panel {
  animation: session-fork-pulse 560ms ease-out;
}

.session-fork-arrive {
  animation: session-fork-arrive 900ms ease-out;
}

@keyframes session-fork-pulse {
  0% {
    transform: translateX(0);
    filter: none;
  }
  35% {
    transform: translateX(8px);
    filter: drop-shadow(
      -6px 0 0 color-mix(in srgb, var(--chat-accent) 35%, transparent)
    );
  }
  100% {
    transform: translateX(0);
    filter: none;
  }
}

@keyframes session-fork-arrive {
  0% {
    transform: translateX(-10px);
    background: color-mix(in srgb, var(--chat-accent) 22%, transparent);
  }
  100% {
    transform: translateX(0);
    background: transparent;
  }
}

.dark .chat-page-shell .composer-root {
  background: var(--chat-paper);
  border-color: rgba(75, 227, 136, 0.3);
  box-shadow: 4px 4px 0 rgba(75, 227, 136, 0.15);
}

.dark .chat-page-shell .composer-root:focus-within {
  box-shadow: 2px 2px 0 rgba(75, 227, 136, 0.2);
}

.chat-persistence-banner {
  background: var(--amber);
  color: #1c211b;
}

.dark .chat-persistence-banner {
  background: #c98a2e;
  color: #0c1510;
}

.chat-persistence-track {
  display: flex;
  width: max-content;
  gap: 2rem;
  white-space: nowrap;
  animation: chat-persistence-scroll 18s linear infinite;
}

@keyframes chat-persistence-scroll {
  from {
    transform: translateX(0);
  }

  to {
    transform: translateX(-50%);
  }
}

/* ─── Mobile/tablet session card grid ─── */
/* Fit an injected lesson-map SVG into its hero band without overflowing. */
.session-card-hero-svg > svg {
  width: 100%;
  height: 100%;
  max-height: 100%;
  object-fit: contain;
}

/* ─── Artifact browser overlay styling ─── */
.artifact-browser-overlay {
  border-left: 2px solid var(--border);
  box-shadow: -4px 0 16px rgba(0, 0, 0, 0.15);
}

.dark .artifact-browser-overlay {
  border-left: 2px solid rgba(75, 227, 136, 0.2);
}

/* ─── Retro scrollbars ─── */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 0;
}

.dark ::-webkit-scrollbar-thumb {
  background: rgba(75, 227, 136, 0.2);
}

/* ────────────────────────────────────────────────────────────────
   WebMCP widget — keep the bridge registered for MCP clients but hide
   the injected floating trigger. Its fixed bottom-right position
   overlapped the chat composer's send button on small screens.
   ──────────────────────────────────────────────────────────────── */
[data-webmcp-widget] {
  display: none !important;
}

/* ────────────────────────────────────────────────────────────────
   Chat message styling (from brand reference keating-chat.html)
   ──────────────────────────────────────────────────────────────── */
.chat-page-shell .chat-avatar {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border: 1.5px solid var(--chat-ink);
  background: var(--card);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 2px 2px 0 var(--chat-ink);
  overflow: hidden;
}

.chat-page-shell .chat-avatar > img {
  width: 30px;
  height: auto;
}

.chat-page-shell .chat-avatar-you {
  background: var(--green-wash);
  color: var(--green-deep);
}

.dark .chat-page-shell .chat-avatar-you {
  background: rgba(75, 227, 136, 0.12);
  color: var(--phosphor);
}

.chat-page-shell .chat-avatar-you > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.chat-page-shell .msg-meta {
  font-family: var(--mono-body);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted-foreground);
  margin-bottom: 6px;
}

.chat-page-shell .msg-meta b {
  color: var(--green-deep);
  font-weight: 600;
}

.dark .chat-page-shell .msg-meta b {
  color: var(--phosphor);
}

/* Keating replies sit directly on the chat page surface. The surrounding page
   carries the study-room texture; the agent text should not be boxed. */
.chat-page-shell .keating-bubble {
  position: relative;
  background: transparent;
  border: 0;
  box-shadow: none;
  padding: 0;
  overflow: visible;
}

.dark .chat-page-shell .keating-bubble {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
}

.dark .chat-page-shell .keating-bubble::after {
  content: none;
}

.chat-page-shell .you-bubble {
  background: var(--card);
  border: 1.5px solid var(--chat-ink);
  box-shadow: 3px 3px 0 var(--chat-ink);
  padding: 10px 14px;
}

.dark .chat-page-shell .you-bubble {
  border-color: rgba(75, 227, 136, 0.3);
  box-shadow: 3px 3px 0 rgba(75, 227, 136, 0.15);
}

/* Topbar mode badge */
.chat-page-shell .chat-mode-badge {
  font-family: var(--mono-body);
  font-size: 10px;
  letter-spacing: 0.1em;
  padding: 5px 10px;
  border: 1px solid var(--green);
  color: var(--green-deep);
  background: var(--card);
  white-space: nowrap;
  align-items: center;
}

.dark .chat-page-shell .chat-mode-badge {
  border-color: rgba(75, 227, 136, 0.45);
  color: var(--phosphor);
}

/* Composer dock: hard edges per reference */
.chat-page-shell .composer-root {
  border-radius: 0;
}

.chat-page-shell .composer-hint {
  font-family: var(--mono-body);
  font-size: 10px;
  letter-spacing: 0.08em;
  color: var(--muted-foreground);
}

.chat-page-shell .composer-hint .ok {
  color: var(--green-deep);
}

.dark .chat-page-shell .composer-hint .ok {
  color: var(--phosphor);
}

/* Session sidebar: paper-deep surface, squared list items, CRT footer */
.chat-page-shell .session-sidebar {
  background: var(--sidebar);
}

.chat-page-shell .session-sidebar li > div {
  border-radius: 0;
}

.chat-page-shell .session-sidebar .sb-new {
  border-radius: 0;
  background: var(--green);
  color: #ffffff;
  border: 1.5px solid var(--green-deep);
  box-shadow: 3px 3px 0 var(--green-deep);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 12px;
  transition:
    transform 0.12s,
    box-shadow 0.12s;
}

.chat-page-shell .session-sidebar .sb-new:hover {
  transform: translate(-1px, -1px);
  box-shadow: 4px 4px 0 var(--green-deep);
  background: var(--green);
}

.chat-page-shell .session-sidebar .sb-new:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 var(--green-deep);
}

.dark .chat-page-shell .session-sidebar .sb-new {
  background: var(--phosphor);
  color: var(--crt);
}

.chat-page-shell .sb-foot {
  position: relative;
  flex-shrink: 0;
  border-top: 1.5px solid var(--chat-ink);
  background: var(--crt);
  padding: 11px 16px;
  overflow: hidden;
}

.chat-page-shell .sb-foot::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.18) 0 1px,
    transparent 1px 3px
  );
}

.chat-page-shell .sb-foot > div {
  font-family: var(--mono-body);
  font-size: 10.5px;
  letter-spacing: 0.1em;
  color: var(--phosphor-dim);
  display: flex;
  align-items: center;
  gap: 8px;
  line-height: 2;
}

.chat-page-shell .sb-foot b {
  color: var(--phosphor);
  font-weight: 600;
}

.chat-page-shell .sb-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  flex-shrink: 0;
  animation: chat-pulse-ring 2.4s infinite;
}

@keyframes chat-pulse-ring {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(30, 155, 80, 0.5);
  }
  55% {
    box-shadow: 0 0 0 6px rgba(30, 155, 80, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .chat-brand,
  .chat-brand img,
  .chat-page-shell .sb-dot {
    transition: none;
    animation: none;
  }
}

/* ---------------------------------------------------------------------------
   Flashcards — 3D flip, swipe drag, exit/enter transitions, streak pop
   --------------------------------------------------------------------------- */

.flashcard-stage {
  perspective: 1200px;
  touch-action: pan-y;
}

.flashcard-3d {
  display: grid;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 320ms cubic-bezier(0.4, 0.2, 0.2, 1);
  will-change: transform;
}

.flashcard-3d.flashcard-flipped {
  transform: rotateY(180deg);
}

/* While dragging, the inline transform drives position — kill the transition
   so the card tracks the pointer 1:1. */
.flashcard-3d.flashcard-dragging {
  transition: none;
}

.flashcard-face {
  grid-area: 1 / 1;
  min-width: 0;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  transform: rotateY(0deg);
  transition: opacity 120ms ease-out;
}

.flashcard-face-back {
  transform: rotateY(180deg);
}

.flashcard-3d:not(.flashcard-flipped) .flashcard-face-back,
.flashcard-3d.flashcard-flipped .flashcard-face:not(.flashcard-face-back) {
  opacity: 0;
  pointer-events: none;
}

@keyframes flashcard-exit-left {
  to { transform: translateX(-130%) rotate(-10deg); opacity: 0; }
}
@keyframes flashcard-exit-right {
  to { transform: translateX(130%) rotate(10deg); opacity: 0; }
}
@keyframes flashcard-exit-up {
  to { transform: translateY(-120%) rotate(3deg); opacity: 0; }
}
@keyframes flashcard-exit-down {
  to { transform: translateY(120%) rotate(-3deg); opacity: 0; }
}
@keyframes flashcard-exit-fade {
  to { transform: scale(0.92); opacity: 0; }
}

.flashcard-exit-left  { animation: flashcard-exit-left 200ms ease-in forwards; }
.flashcard-exit-right { animation: flashcard-exit-right 200ms ease-in forwards; }
.flashcard-exit-up    { animation: flashcard-exit-up 200ms ease-in forwards; }
.flashcard-exit-down  { animation: flashcard-exit-down 200ms ease-in forwards; }
.flashcard-exit-fade  { animation: flashcard-exit-fade 170ms ease-in forwards; }

@keyframes flashcard-enter {
  from { transform: translateY(14px) scale(0.97); opacity: 0; }
  to   { transform: translateY(0) scale(1); opacity: 1; }
}
.flashcard-enter { animation: flashcard-enter 200ms ease-out; }

@keyframes flashcard-streak-pop {
  0%   { transform: scale(1); }
  40%  { transform: scale(1.35); }
  100% { transform: scale(1); }
}
.flashcard-streak-pop { animation: flashcard-streak-pop 320ms ease-out; }

@keyframes flashcard-milestone-pulse {
  0%   { box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.55); }
  100% { box-shadow: 0 0 0 12px rgba(245, 158, 11, 0); }
}
.flashcard-milestone-pulse { animation: flashcard-milestone-pulse 650ms ease-out 2; }

@media (prefers-reduced-motion: reduce) {
  .flashcard-3d {
    transition: none;
  }
  .flashcard-exit-left,
  .flashcard-exit-right,
  .flashcard-exit-up,
  .flashcard-exit-down,
  .flashcard-exit-fade,
  .flashcard-enter,
  .flashcard-streak-pop,
  .flashcard-milestone-pulse {
    animation-duration: 1ms;
    animation-iteration-count: 1;
  }
}

